    difficulty: 'beginner' | 'intermediate' | 'advanced';
  };
  authorId: string;
}
```

### 执行流程

```
1. 从 DB 查询 documentIds 对应的 extracted_text
2. 构建 Prompt，调用 Gemini（gemini-2.0-flash）
3. Gemini 返回极简 QuizDSL JSON
4. quizCompiler.compileToCourse(dsl, authorId) → 完整 Course JSON + 所有 UUID
5. CourseSchema.safeParse 验证
6. 写入 courses 表（status: 'draft'）
7. 写入 lessons 表（content_json）
8. 返回 { courseId, courseTitle }
```

### quizCompiler.ts（DSL 类型 + 编译逻辑）

```typescript
// --- DSL 类型定义（AI 输出的极简格式）---
type MCQuestion    = { type: 'mc' | 'mc_multi'; q: string; opts: string[]; exp: string };
// opts 中正确答案末尾带 * 号，编译器负责解析并去除
// 示例：["错误选项A", "正确答案B*", "错误选项C", "错误选项D"]

type TFQuestion    = { type: 'tf'; stmt: string; ans: boolean; exp: string };
type MatchQuestion = { type: 'match'; pairs: [string, string][] };  // 无 explanation

type QuizDSL = {
  title: string;
  description?: string;
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  questions: (MCQuestion | TFQuestion | MatchQuestion)[];
};

// --- 编译器主函数 ---
export function compileToCourse(dsl: QuizDSL, authorId: string): Course {
  return {
    schema_version: '1.0',
    course_id: crypto.randomUUID(),
    metadata: {
      title: dsl.title,
      description: dsl.description ?? '',
      difficulty_level: dsl.difficulty,
      estimated_minutes: dsl.questions.length * 2,
      tags: ['AI生成', '测验'],
      author: { userId: authorId, displayName: 'AI Tutor' },
    },
    lessons: [{
      lesson_id: crypto.randomUUID(),
      title: '测验',
      pages: dsl.questions.map((q, i) => ({
        page_id: crypto.randomUUID(),
        order: i,
        blocks: [compileBlock(q)],
      })),
    }],
  };
}

function compileBlock(q: MCQuestion | TFQuestion | MatchQuestion): Block {
  const optIds = ['opt-a', 'opt-b', 'opt-c', 'opt-d', 'opt-e'];

  if (q.type === 'mc' || q.type === 'mc_multi') {
    return {
      id: crypto.randomUUID(),
      type: 'multiple-choice',
      position: { order: 0 },
      content: {
        question: q.q,
        options: q.opts.map((text, i) => ({
          id: optIds[i],
          text: text.replace(/\*$/, ''),   // 去掉末尾 * 号
          isCorrect: text.endsWith('*'),
        })),
        allowMultiple: q.type === 'mc_multi',
        explanation: q.exp,
      },
    };
  }

  if (q.type === 'tf') {
    return {
      id: crypto.randomUUID(),
      type: 'true-false',
      position: { order: 0 },
      content: { statement: q.stmt, isTrue: q.ans, explanation: q.exp },
    };
  }

  // match
  return {
    id: crypto.randomUUID(),
    type: 'matching',
    position: { order: 0 },
    content: {
      pairs: q.pairs.map(([left, right], i) => ({ id: `p${i + 1}`, left, right })),
      mode: 'list',
    },
  };
}
```

### Gemini Prompt

```
你是一位考试辅导老师，根据以下学习材料生成考前复习测验。

语言规则：输出语言与学习材料主要语言一致，不得混用。

## 学习材料
[文件1: {filename}]
{extracted_text_1}

[文件2: {filename}]
{extracted_text_2}

## 生成要求
- 总题数：{questionCount} 题
- 难度：{difficulty}（beginner=基础概念，intermediate=理解和应用，advanced=分析和综合）
- 覆盖材料中的核心考点，题目由易到难排列
- 题型比例：mc 40% / mc_multi 20% / tf 20% / match 20%
- mc_multi 的 q 字段中注明"多选"或"Select all that apply"
- 正确答案在 opts 末尾加 * 标记（match 无需标记）
- exp 字段（mc 和 tf 必填）：
  * 答错场景：解释为什么错，指出常见误解
  * 答对场景：补充知识点上下文和关联概念
  * 2-4句，引用原文概念，禁止写"答案是X"

## 输出格式
只输出 JSON，直接从 { 开始，不要 markdown 包裹：

{
  "title": "...",
  "description": "一句话描述测验覆盖的主题",
  "difficulty": "{difficulty}",
  "questions": [
    { "type": "mc",       "q": "...",       "opts": ["A", "B*", "C", "D"],        "exp": "..." },
    { "type": "mc_multi", "q": "...（多选）","opts": ["A*", "B*", "C", "D"],       "exp": "..." },
    { "type": "tf",       "stmt": "...",    "ans": true,                           "exp": "..." },
    { "type": "match",    "pairs": [["左1","右1"],["左2","右2"],["左3","右3"],["左4","右4"]] }
  ]
}
```

### Token 效率对比

| 方案 | 每题 tokens | 30题总量 | 单次调用可行 |
|------|------------|---------|------------|
| 完整 Course JSON | ~225 | ~7,500 | 危险 |
| **极简 DSL + 编译器** | **~55** | **~1,650** | **安全** |

节省约 4.5 倍，30题一次调用完成，UUID 和结构由编译器代码保证，不依赖 AI。
